 public static void CheckBinaries(BC c){if(BN.Hash(Initdb)!=InitdbHash||BN.Hash(@"C:\Program Files\PostgreSQL\17\bin\postgres.exe")!=(string)c.manifest["postgresHash"]||BN.Hash(@"C:\Windows\System32\cmd.exe")!=(string)c.manifest["cmdHash"])throw new Exception("PINNED_BINARY_DRIFT");
