 public static void IssueRelease(BC c,string reference){
  if(!c.real||WindowsIdentity.GetCurrent().User.Value!=Sid||!System.Text.RegularExpressions.Regex.IsMatch(reference,"^R24-EXEC-[a-z0-9-]{8,80}$"))throw new Exception("NEW_EXECUTION_REFERENCE_REQUIRED");
  BN.ConsoleOwned(true);Console.WriteLine("ONLY AFTER new explicit execution approval. This issues ONE run/source-bound release, not a password.");Console.WriteLine("Type exactly: "+Phrase(c,reference));
  var entry=new StringBuilder();var inputWatch=Stopwatch.StartNew();bool complete=false;while(inputWatch.ElapsedMilliseconds<120000){if(Console.KeyAvailable){var key=Console.ReadKey(true);if(key.Key==ConsoleKey.Enter){complete=true;break;}if(key.Key==ConsoleKey.Escape)throw new Exception("APPROVAL_CANCELLED");if(key.Key==ConsoleKey.Backspace){if(entry.Length>0)entry.Length--;}else if(!Char.IsControl(key.KeyChar)&&entry.Length<512)entry.Append(key.KeyChar);}System.Threading.Thread.Sleep(20);}if(!complete||entry.ToString()!=Phrase(c,reference))throw new Exception("OPERATOR_APPROVAL_MISMATCH_OR_TIMEOUT");Preflight(c);
  var now=DateTimeOffset.UtcNow;var claims=new{phase="13.5D.1G-R2.4-EXECUTION",runId=Path.GetFileName(c.run),manifestHash=c.manifestHash,bundleHash=c.manifest["bundleHash"],operatorSid=Sid,target=Data,maxAttempts=1,reference=reference,issuedAt=now.ToString("o"),expiresAt=now.AddMinutes(10).ToString("o"),serverStartupApproved=false,sqlApproved=false};
