  string path=Path.Combine(c.run,"execution-release.dpapi");using(var f=new FileStream(path,FileMode.CreateNew,FileSystemRights.Write,FileShare.Read,4096,FileOptions.None,security)){f.Write(sealedBytes,0,sealedBytes.Length);f.Flush(true);}CheckAcl(File.GetAccessControl(path));
  c.Save("release-issued.json",new{runId=Path.GetFileName(c.run),manifestHash=c.manifestHash,bundleHash=c.manifest["bundleHash"],reference=reference,expiresAt=now.AddMinutes(10).ToString("o"),serverStartupApproved=false,sqlApproved=false});
